export const AUTH_HTTP_ERROR = 'AUTH_HTTP_ERROR'
export const AUTH_SESSION_ERROR = 'AUTH_SESSION_ERROR'
export const AUTH_COOKIE_ERROR = 'AUTH_COOKIE_ERROR'
export const AUTH_SUCCESS = 'AUTH_SUCCESS'


export function authHttpError(error) {
  return {
    type: AUTH_HTTP_ERROR,
    error: error
  }
}

export function authSessionError(error) {
  return {
    type: AUTH_SESSION_ERROR,
    error: error
  }
}

export function authCookieError(error) {
  return {
    type: AUTH_COOKIE_ERROR,
    error: error
  }
}

export function authSuccess(userData) {
  return {
    type: AUTH_SUCCESS,
    userData: userData
  }
}

export function fetchAuth() {
  //console.log('fetch auth');
  return dispatch => {
    //dispatch(requestAuth())
    return fetch('https://scbm.amfdev.co.uk/api/auth/', {
      method: "GET",
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
        'Cache': 'no-cache'
      },
      credentials: 'include'
      })
      .then(response => catchAuthHttpError(response, dispatch))
      .then(response => response.json())
      .then(json => catchAuthSessionError(json, dispatch))
      .then(json => catchAuthCookieError(json, dispatch))
      .then(json => doAuthSuccess(json, dispatch))
      .catch(error => console.log(error));
  }

}

// Handle HTTP errors since fetch won't.
function catchAuthHttpError(response, dispatch) {
   //console.log('catchAuthHttpError')
  if (!response.ok) {
     dispatch(authHttpError(response.statusText))
    throw Error(response.statusText);
  }
  return response;
}

function catchAuthSessionError(json, dispatch) {
   //console.log('catchAuthSessionError')
    if (!json.sessionValid) {
        dispatch(authSessionError(json.authError))
        throw Error(json.authError);
    }
    
  return json;
}

function catchAuthCookieError(json, dispatch) {
   //console.log('catchAuthCookieError')
    if (!json.scCookiesValid) {
        dispatch(authCookieError(json.authError))
        throw Error(json.authError);
    }
    
  return json;
}


function doAuthSuccess(json, dispatch) {
   //console.log('authSuccess')
    if (json.authSuccess) {
        dispatch(authSuccess(json.userData))
    }
    
  return json;
}




